-- Durable ordering excludes high frequency observation timestamps/bytes.
ALTER TABLE torrents ADD COLUMN catalog_version TEXT NOT NULL DEFAULT '';
ALTER TABLE torrents ADD COLUMN read_version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE read_model_version(singleton INTEGER PRIMARY KEY CHECK(singleton=1), version INTEGER NOT NULL);
INSERT INTO read_model_version VALUES(1,1);
CREATE TRIGGER version_torrents_insert AFTER INSERT ON torrents BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_torrents_delete AFTER DELETE ON torrents BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=OLD.hash; END;
CREATE TRIGGER version_torrents_update AFTER UPDATE OF name,size,state,error,source_uri,is_temporary,title,data,poster,category,deletion_mode,deletion_error,metadata_known,piece_length,num_pieces,metadata_format,catalog_version ON torrents WHEN OLD.name IS NOT NEW.name OR OLD.size IS NOT NEW.size OR OLD.state IS NOT NEW.state OR OLD.error IS NOT NEW.error OR OLD.source_uri IS NOT NEW.source_uri OR OLD.is_temporary IS NOT NEW.is_temporary OR OLD.title IS NOT NEW.title OR OLD.data IS NOT NEW.data OR OLD.poster IS NOT NEW.poster OR OLD.category IS NOT NEW.category OR OLD.deletion_mode IS NOT NEW.deletion_mode OR OLD.deletion_error IS NOT NEW.deletion_error OR OLD.metadata_known IS NOT NEW.metadata_known OR OLD.piece_length IS NOT NEW.piece_length OR OLD.num_pieces IS NOT NEW.num_pieces OR OLD.metadata_format IS NOT NEW.metadata_format OR OLD.catalog_version IS NOT NEW.catalog_version BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_files_insert AFTER INSERT ON files BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_files_delete AFTER DELETE ON files BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=OLD.hash; END;
CREATE TRIGGER version_files_update AFTER UPDATE OF path,size,priority,is_media,file_offset,offset_known ON files WHEN OLD.path IS NOT NEW.path OR OLD.size IS NOT NEW.size OR OLD.priority IS NOT NEW.priority OR OLD.is_media IS NOT NEW.is_media OR OLD.file_offset IS NOT NEW.file_offset OR OLD.offset_known IS NOT NEW.offset_known BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_torrent_intents_insert AFTER INSERT ON torrent_intents BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_torrent_intents_delete AFTER DELETE ON torrent_intents BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=OLD.hash; END;
CREATE TRIGGER version_torrent_intents_update AFTER UPDATE OF record_id,run_intent,revision,runtime_attachment,applied_revision,observed_state,observed_error ON torrent_intents WHEN OLD.record_id IS NOT NEW.record_id OR OLD.run_intent IS NOT NEW.run_intent OR OLD.revision IS NOT NEW.revision OR OLD.runtime_attachment IS NOT NEW.runtime_attachment OR OLD.applied_revision IS NOT NEW.applied_revision OR OLD.observed_state IS NOT NEW.observed_state OR OLD.observed_error IS NOT NEW.observed_error BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_torrent_storage_insert AFTER INSERT ON torrent_storage BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_torrent_storage_delete AFTER DELETE ON torrent_storage BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=OLD.hash; END;
CREATE TRIGGER version_torrent_storage_update AFTER UPDATE OF version,root,state,manifest,error ON torrent_storage WHEN OLD.version IS NOT NEW.version OR OLD.root IS NOT NEW.root OR OLD.state IS NOT NEW.state OR OLD.manifest IS NOT NEW.manifest OR OLD.error IS NOT NEW.error BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_torrent_activation_blocks_insert AFTER INSERT ON torrent_activation_blocks BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=(SELECT hash FROM torrent_intents WHERE record_id=NEW.record_id); END;
CREATE TRIGGER version_torrent_activation_blocks_delete AFTER DELETE ON torrent_activation_blocks BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=(SELECT hash FROM torrent_intents WHERE record_id=OLD.record_id); END;
CREATE TRIGGER version_torrent_activation_blocks_update AFTER UPDATE OF kind,reason ON torrent_activation_blocks WHEN OLD.kind IS NOT NEW.kind OR OLD.reason IS NOT NEW.reason BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=(SELECT hash FROM torrent_intents WHERE record_id=NEW.record_id); END;
CREATE TRIGGER version_torrent_download_blocks_insert AFTER INSERT ON torrent_download_blocks BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
