CREATE TRIGGER version_torrent_download_blocks_update AFTER UPDATE OF reason ON torrent_download_blocks WHEN OLD.reason IS NOT NEW.reason BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_torrent_order_insert AFTER INSERT ON torrent_order BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=NEW.hash; END;
CREATE TRIGGER version_torrent_order_delete AFTER DELETE ON torrent_order BEGIN UPDATE read_model_version SET version=version+1 WHERE singleton=1; UPDATE torrents SET read_version=(SELECT version FROM read_model_version WHERE singleton=1) WHERE hash=OLD.hash; END;
